SET LOCAL lock_timeout = '2s';--> statement-breakpoint
CREATE OR REPLACE VIEW "public"."v_campaign_total_usd" AS (SELECT campaign_id, COALESCE(SUM(net), 0) as total FROM (SELECT d.campaign_id as campaign_id, dists.net as net FROM donations d INNER JOIN dists ON dists.donation_id = d.id WHERE d.campaign_id IS NOT NULL AND dists.status = 'settled' AND d.status = 'settled' UNION ALL SELECT c.id as campaign_id, dists.net as net FROM campaigns c INNER JOIN dists ON dists.fund_id = c.legacy_fund_id INNER JOIN donations ON donations.id = dists.donation_id WHERE c.legacy_fund_id IS NOT NULL AND dists.status = 'settled' AND donations.status = 'settled') s GROUP BY campaign_id);
